{
  "name": "write_file",
  "arguments": {
    "path": "todo.py",
    "content": "#!/usr/bin/env python3
import sys
import json

todo_file = 'todos.json'

def load_todos():
    try:
        with open(todo_file, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        return []

def save_todos(todos):
    with open(todo_file, 'w') as f:
        json.dump(todos, f, indent=4)

if len(sys.argv) < 2:
    print('Usage: python3 todo.py [add|list|done] [task_id|task_text]')
    sys.exit(1)

command = sys.argv[1]
todos = load_todos()

if command == 'add':
    if len(sys.argv) < 3:
        print('Usage: python3 todo.py add "task_text"')
        sys.exit(1)
    task_text = ' '.join(sys.argv[2:])
    todos.append({'text': task_text, 'done': False})
    save_todos(todos)
elif command == 'list':
    for i, todo in enumerate(todos):
        status = 'Done' if todo['done'] else 'Pending'
        print(f'{i + 1}. {todo["text"]} - {status}')
elif command == 'done':
    if len(sys.argv) < 3:
        print('Usage: python3 todo.py done task_id')
        sys.exit(1)
    try:
        task_id = int(sys.argv[2]) - 1
        if 0 <= task_id < len(todos):
            todos[task_id]['done'] = True
            save_todos(todos)
        else:
            print('Invalid task ID.')
    except ValueError:
        print('Task ID must be an integer.')
else:
    print('Unknown command. Use add, list, or done.')"
  }
}
